// ── WebSocket client with reconnection logic ──────────────────
function createReconnectingWebSocket(url, handlers) {
  let ws = null;
  let reconnectDelay = 1000;
  const MAX_DELAY = 30000;

  function connect() {
    ws = new WebSocket(url);

    ws.addEventListener('open', () => {
      reconnectDelay = 1000; // reset on success
      handlers.onOpen?.();
    });

    ws.addEventListener('message', ({ data }) => {
      try {
        handlers.onMessage?.(JSON.parse(data));
      } catch {
        handlers.onMessage?.(data); // handle non-JSON messages
      }
    });

    ws.addEventListener('close', ({ code, reason, wasClean }) => {
      handlers.onClose?.({ code, reason, wasClean });
      if (!wasClean && code !== 1000) {
        // Exponential backoff reconnect
        setTimeout(() => {
          reconnectDelay = Math.min(reconnectDelay * 2, MAX_DELAY);
          connect();
        }, reconnectDelay);
      }
    });

    ws.addEventListener('error', (err) => {
      handlers.onError?.(err);
    });
  }

  connect();

  return {
    send(data) {
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(typeof data === 'string' ? data : JSON.stringify(data));
      } else {
        console.warn('WebSocket not open, message dropped');
      }
    },
    close() { ws?.close(1000, 'Client closed'); },
  };
}

// ── Server-Sent Events client ─────────────────────────────────
function createSSEConnection(url, handlers) {
  // EventSource handles reconnection and Last-Event-ID automatically
  const es = new EventSource(url, { withCredentials: true });

  es.addEventListener('message', ({ data, lastEventId }) => {
    handlers.onMessage?.(JSON.parse(data), lastEventId);
  });

  // Custom named events
  es.addEventListener('notification', ({ data }) => {
    handlers.onNotification?.(JSON.parse(data));
  });

  es.addEventListener('error', () => {
    if (es.readyState === EventSource.CLOSED) {
      handlers.onClose?.();
    }
    // EventSource.CONNECTING means auto-reconnecting
  });

  return { close: () => es.close() };
}

// ── Polling with exponential backoff ─────────────────────────
async function poll(fetchFn, onData, { interval = 5000 } = {}) {
  let active = true;
  async function tick() {
    if (!active) return;
    try {
      const data = await fetchFn();
      onData(data);
    } catch (err) {
      console.warn('Poll failed:', err);
    }
    if (active) setTimeout(tick, interval);
  }
  tick();
  return { stop: () => { active = false; } };
}

