// ── WebSocket readyState values ───────────────────────────────
const WS_STATES = {
  0: 'CONNECTING — handshake in progress',
  1: 'OPEN       — connected, can send/receive',
  2: 'CLOSING    — close handshake in progress',
  3: 'CLOSED     — connection terminated',
};
// Always check ws.readyState === WebSocket.OPEN before calling ws.send()

// ── WebSocket close codes ─────────────────────────────────────
const WS_CLOSE_CODES = {
  1000: 'Normal closure',
  1001: 'Going away (page navigating)',
  1002: 'Protocol error',
  1003: 'Unsupported data type',
  1006: 'Abnormal closure (no close frame — network error)',
  1007: 'Invalid data (e.g. non-UTF8 in text frame)',
  1008: 'Policy violation',
  1009: 'Message too large',
  1011: 'Server internal error',
  4000: 'App-defined codes start at 4000',
};
// Code 1006 means no close frame was received — reconnect needed

